import { formatNumber, msg, t } from "./i18n.js";
import { randomId } from "./lib.js";
// Drafts, submission receipts, and a bounded cache of originals Hermes may omit.
import { databaseName } from "./profile-context.js";
const MAX_IMAGE = 2 * 1024 * 1024;
export const MAX_IMAGES_TOTAL = 6 * 1024 * 1024;
const TYPES = new Set(["image/png", "image/jpeg", "image/webp", "image/gif"]);
let database;
function openDatabase() {
  if (!database) {
    let abandoned = false;
    const opening = new Promise((resolve, reject) => {
      const request = indexedDB.open(databaseName, 1);
      request.onupgradeneeded = () =>
        request.result.createObjectStore("pending");
      request.onsuccess = () => {
        const db = request.result;
        if (abandoned) {
          db.close();
          return;
        }
        db.onversionchange = () => {
          db.close();
          if (database === opening) database = null;
        };
        db.onclose = () => {
          if (database === opening) database = null;
        };
        resolve(db);
      };
      request.onerror = () =>
        reject(
          new Error(msg("Browser storage is unavailable. Try again or enable storage for Talaria.")),
        );
      request.onblocked = () => {
        abandoned = true;
        reject(
          new Error(msg("Close other Talaria tabs and try saving this attachment again.")),
        );
      };
    }).catch((error) => {
      if (database === opening) database = null;
      throw error;
    });
    database = opening;
  }
  return database;
}
export async function pendingStorage(key, value) {
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const write = arguments.length > 1;
    const transaction = db.transaction(
      "pending",
      write ? "readwrite" : "readonly",
    );
    const store = transaction.objectStore("pending");
    const request = write
      ? value === null
        ? store.delete(key)
        : store.put(value, key)
      : store.get(key);
    transaction.oncomplete = () => resolve(request.result);
    transaction.onabort = transaction.onerror = () =>
      reject(
        new Error(msg("The images could not be saved in this browser. Free some browser storage and try again.")),
      );
  });
}

export async function consumePendingImages(key, images) {
  const ids = new Set(images.map((image) => image.id));
  if (!ids.size) return;
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction("pending", "readwrite");
    const records = transaction.objectStore("pending");
    const request = records.get(key);
    request.onsuccess = () => {
      if (!Array.isArray(request.result)) return;
      const remaining = request.result.filter((image) => !ids.has(image.id));
      if (remaining.length) records.put(remaining, key);
      else records.delete(key);
    };
    transaction.oncomplete = resolve;
    transaction.onabort = transaction.onerror = () =>
      reject(new Error(msg("The image draft could not be updated in this browser.")));
  });
}

const draftWork = new Map();
export function beginPendingImages(key) {
  const work = draftWork.get(key) || new Set();
  let finish;
  const pending = new Promise((resolve) => {
    finish = resolve;
  });
  work.add(pending);
  draftWork.set(key, work);
  return () => {
    work.delete(pending);
    if (!work.size) draftWork.delete(key);
    finish();
  };
}

export async function migratePendingImages(from, to) {
  if (from === to) return;
  while (draftWork.has(from) || draftWork.has(to))
    await Promise.all([...(draftWork.get(from) || []), ...(draftWork.get(to) || [])]);
  // Text-only sessions remain usable when the browser disables IndexedDB.
  const db = await openDatabase().catch(() => null);
  if (!db) return;
  return new Promise((resolve, reject) => {
    const transaction = db.transaction("pending", "readwrite");
    const records = transaction.objectStore("pending");
    const source = records.get(from);
    const target = records.get(to);
    let failure;
    target.onsuccess = () => {
      try {
        if (!Array.isArray(source.result) || !source.result.length) return;
        const combined = Array.isArray(target.result) ? [...target.result] : [];
        const ids = new Set(combined.map((image) => image.id));
        for (const image of source.result) {
          if (!ids.has(image.id)) combined.push(image);
          ids.add(image.id);
        }
        if (
          combined.length > 4 ||
          combined.reduce((size, image) => size + image.size, 0) > MAX_IMAGES_TOTAL
        )
          throw Object.assign(
            new Error(msg("Both sessions have image drafts. Remove some attachments before reopening the continued session (four images, 6 MB maximum).")),
            { code: "draft_conflict" },
          );
        records.put(combined, to);
        records.delete(from);
      } catch (error) {
        failure = error;
        try {
          transaction.abort();
        } catch {
          // An already-aborted transaction will reject through onabort.
        }
      }
    };
    transaction.oncomplete = resolve;
    transaction.onabort = transaction.onerror = () =>
      reject(
        failure || new Error(msg("The image draft could not be moved in this browser.")),
      );
  });
}

const CACHE_LIMIT = 32 * 1024 * 1024;
// Hermes keeps a message's time and text when compaction re-saves it under a
// new ID, and a branch copies both. Together they still find its originals.
export function imageFingerprint(message) {
  const stamp = Number(message?.timestamp);
  const content = message?.content;
  if (typeof content !== "string" || !Number.isFinite(stamp)) return null;
  let hash = 0x811c9dc5;
  for (let i = 0; i < content.length; i++) hash = Math.imul(hash ^ content.charCodeAt(i), 0x01000193);
  return `${stamp}:${content.length}:${(hash >>> 0).toString(36)}`;
}
const cacheError =
  msg("This browser could not retain the image. Download a copy to keep it.");
function imageIndex(value) {
  return Array.isArray(value)
    ? value.filter(
        (item) =>
          item &&
          typeof item.key === "string" &&
          item.key.startsWith("image.") &&
          typeof item.session === "string" &&
          Number.isFinite(item.bytes) &&
          item.bytes >= 0,
      )
    : [];
}
export async function cacheMessageImages(
  session,
  messageId,
  images,
  receipt = null,
  fingerprint = null,
) {
  const bytes = images.reduce((n, image) => n + image.url.length, 0);
  // Reject before evicting or deleting the submission receipt. Otherwise a
  // single oversized entry is removed from the index and then stored orphaned.
  if (bytes > CACHE_LIMIT) throw new Error(cacheError);
  const db = await openDatabase();
  const key = `image.${session}.${messageId}`;
  return new Promise((resolve, reject) => {
    const transaction = db.transaction("pending", "readwrite");
    const records = transaction.objectStore("pending");
    const request = records.get("image-index");
    request.onsuccess = () => {
      try {
        const previous = imageIndex(request.result);
        const index = previous.filter((item) => item.key !== key);
        index.push({
          key,
          session,
          messageId,
          bytes,
          ...(fingerprint ? { fingerprint } : {}),
        });
        let size = index.reduce((n, item) => n + item.bytes, 0);
        while (index.length > 100 || size > CACHE_LIMIT) {
          const oldest = index.shift();
          size -= oldest.bytes;
          records.delete(oldest.key);
        }
        if (receipt) records.delete(receipt);
        records.put(images, key);
        records.put(index, "image-index");
      } catch {
        transaction.abort();
      }
    };
    transaction.oncomplete = resolve;
    transaction.onabort = transaction.onerror = () =>
      reject(new Error(cacheError));
  });
}
export async function browserAttachments(session, ids = null, fingerprints = null) {
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    // The index and originals form one snapshot, with one transaction even
    // when a session has many cached attachments.
    const transaction = db.transaction("pending", "readonly");
    const records = transaction.objectStore("pending");
    const request = records.get("image-index");
    const rows = [];
    request.onsuccess = () => {
      try {
        for (const item of imageIndex(request.result)
          .filter(
            (item) =>
              (item.session === session && (!ids || ids.has(item.messageId))) ||
              (fingerprints && fingerprints.has(item.fingerprint)),
          )
          .slice(-100)) {
          const images = records.get(item.key);
          images.onsuccess = () => {
            if (Array.isArray(images.result) && images.result.length)
              rows.push({ message_id: item.messageId, session: item.session,
                fingerprint: item.fingerprint, images: images.result });
          };
        }
      } catch {
        transaction.abort();
      }
    };
    transaction.oncomplete = () => resolve(rows);
    transaction.onabort = transaction.onerror = () =>
      reject(new Error(cacheError));
  });
}
export async function forgetImages(session) {
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction("pending", "readwrite");
    const records = transaction.objectStore("pending");
    const request = records.get("image-index");
    const receipts = records.openCursor(
      IDBKeyRange.bound(`run.${session}.`, `run.${session}.\uffff`),
    );
    receipts.onsuccess = () => {
      const cursor = receipts.result;
      if (!cursor) return;
      // Session identifiers can contain dots. A key prefix alone also matches
      // other sessions, so confirm the session in the receipt itself.
      if (cursor.value?.payload?.session_id === session) cursor.delete();
      cursor.continue();
    };
    request.onsuccess = () => {
      const index = imageIndex(request.result);
      for (const item of index)
        if (item.session === session) records.delete(item.key);
      records.put(
        index.filter((item) => item.session !== session),
        "image-index",
      );
    };
    transaction.oncomplete = resolve;
    transaction.onabort = transaction.onerror = () =>
      reject(new Error(cacheError));
  });
}
// The originals this browser kept for these messages, by their current IDs.
export async function cachedAttachments(session, messages) {
  const wanted = messages.filter((message) => placeholderCount(message?.content));
  if (!wanted.length) return new Map();
  const records = await browserAttachments(
    session,
    new Set(wanted.map((message) => message.id)),
    new Set(wanted.map(imageFingerprint).filter(Boolean)),
  ).catch(() => []);
  const byId = new Map(records.filter((item) => item.session === session)
    .map((item) => [item.message_id, item.images]));
  const byFingerprint = new Map(records.filter((item) => item.fingerprint)
    .map((item) => [item.fingerprint, item.images]));
  const found = new Map();
  for (const message of wanted) {
    const images = byId.get(message.id) || byFingerprint.get(imageFingerprint(message));
    if (images) found.set(message.id, images);
  }
  return found;
}
export async function withCachedImages(session, messages) {
  const images = await cachedAttachments(session, messages);
  if (!images.size) return messages;
  return messages.map((message) =>
    images.has(message.id)
      ? { ...message, browserImages: images.get(message.id) }
      : message,
  );
}
function placeholderSuffix(content) {
  const marker = "[screenshot]";
  const end = content.trimEnd().length;
  let offset = end,
    start = end,
    count = 0,
    matched = 0;
  // Walk back from the suffix. A global search retries every earlier marker
  // when a long transcript contains placeholders followed by ordinary text.
  while (
    offset >= marker.length &&
    content.slice(offset - marker.length, offset) === marker
  ) {
    offset -= marker.length;
    count++;
    if (!offset || content[offset - 1] === "\n") {
      start = offset ? offset - 1 : 0;
      matched = count;
    }
    if (content[offset - 1] === "\n") offset--;
  }
  return { start, count: matched };
}
export function placeholderCount(content) {
  return typeof content === "string" ? placeholderSuffix(content).count : 0;
}
export function withoutImagePlaceholders(content) {
  return typeof content === "string"
    ? content.slice(0, placeholderSuffix(content).start)
    : content;
}
export function currentImageMessage(history, live) {
  if (!live?.userImages?.length || typeof live.imageBoundary !== "number")
    return null;
  const projected = [
    live.userText,
    ...live.userImages.map(() => "[screenshot]"),
  ]
    .filter(Boolean)
    .join("\n");
  const candidates = history.filter((message) => {
    if (
      message.role !== "user" ||
      typeof message.id !== "number" ||
      message.id <= live.imageBoundary
    )
      return false;
    if (message.content === projected) return true;
    const images = imageParts(message.content);
    return (
      images.length === live.userImages.length &&
      images.every((image, i) => image.url === live.userImages[i].url)
    );
  });
  return candidates.length === 1 ? candidates[0] : null;
}
export function messageImages(message) {
  const native = imageParts(message.content);
  if (native.length) return native;
  if (Array.isArray(message.browserImages))
    return message.browserImages.map((image) => ({ ...image, cached: true }));
  return Array.from(
    { length: Math.min(4, placeholderCount(message.content)) },
    (_, i) => ({
      name: `Image ${i + 1}`,
      fallbackIndex: i + 1,
      unavailable:
        msg("Hermes saved an image placeholder. The original is not available in this browser."),
    }),
  );
}
function imageParts(content) {
  if (!Array.isArray(content)) return [];
  return content
    .filter((p) => p && ["image_url", "input_image", "image"].includes(p.type))
    .map((p, i) => {
      let url =
        typeof p.image_url === "string" ? p.image_url : p.image_url?.url;
      if (p.type === "image" && p.source?.type === "base64")
        url = `data:${p.source.media_type};base64,${p.source.data}`;
      const safe =
        typeof url === "string" &&
        url.length < 3 * 1024 * 1024 &&
        /^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(url);
      // External images remain explicit links; never load arbitrary hosts or server paths.
      const external = typeof url === "string" && /^https?:\/\//i.test(url);
      return {
        url: safe ? url : null,
        href: external ? url : null,
        name:
          typeof p.name === "string" ? p.name.slice(0, 160) : `Image ${i + 1}`,
        ...(typeof p.name !== "string" ? { fallbackIndex: i + 1 } : {}),
      };
    });
}
function dataURL(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () =>
      reject(new Error(msg("This image could not be read. Attach it again.")));
    reader.readAsDataURL(blob);
  });
}
export async function prepareImage(file) {
  if (!TYPES.has(file.type))
    throw new Error(msg("Choose a PNG, JPEG, WebP, or GIF image."));
  if (file.size > 10 * 1024 * 1024)
    throw new Error(msg("Choose an image smaller than 10 MB."));
  const objectURL = URL.createObjectURL(file);
  let blob = file,
    resized = false;
  try {
    const image = new Image();
    image.src = objectURL;
    try {
      await image.decode();
    } catch {
      throw new Error(msg("This image could not be opened. Try another file."));
    }
    if (
      !image.naturalWidth ||
      image.naturalWidth * image.naturalHeight > 40_000_000
    )
      throw new Error(msg("This image is too large. Choose one with fewer than 40 million pixels."));
    if (
      file.size > MAX_IMAGE ||
      Math.max(image.naturalWidth, image.naturalHeight) > 2560
    ) {
      const scale = Math.min(
        1,
        2560 / Math.max(image.naturalWidth, image.naturalHeight),
      );
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
      canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
      const context = canvas.getContext("2d");
      context.fillStyle = "#ffffff";
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
      for (const quality of [0.9, 0.75, 0.55]) {
        blob = await new Promise((resolve) =>
          canvas.toBlob(resolve, "image/jpeg", quality),
        );
        if (blob && blob.size <= MAX_IMAGE) break;
      }
      resized = true;
    }
    if (!blob || blob.size > MAX_IMAGE)
      throw new Error(msg("This image is still too large. Try a smaller version."));
    return {
      id: randomId(),
      name: file.name || msg("Pasted image"),
      ...(!file.name ? { pastedName: true } : {}),
      url: await dataURL(blob),
      size: blob.size,
      resized,
    };
  } finally {
    URL.revokeObjectURL(objectURL);
  }
}

export function imageName(image) {
  if (image.fallbackIndex) return t("Image {number}", { number: formatNumber(image.fallbackIndex) });
  return image.pastedName ? t("Pasted image") : image.name;
}
